<?php
if(!defined('ABSPATH'))exit;
class Terttus_Brand_Grid_Widget extends \Elementor\Widget_Base{
 public function get_name(){return 'terttus_brand_grid';} public function get_title(){return 'Terttus Brands';} public function get_icon(){return 'eicon-logo';} public function get_categories(){return ['terttus-widgets'];}
 protected function register_controls(){$this->start_controls_section('c',['label'=>'Brands']);$r=new \Elementor\Repeater();$r->add_control('name',['label'=>'Navn','type'=>\Elementor\Controls_Manager::TEXT]);$r->add_control('logo',['label'=>'Logo','type'=>\Elementor\Controls_Manager::MEDIA]);$r->add_control('url',['label'=>'Link','type'=>\Elementor\Controls_Manager::URL]);$this->add_control('items',['type'=>\Elementor\Controls_Manager::REPEATER,'fields'=>$r->get_controls(),'title_field'=>'{{{ name }}}']);$this->end_controls_section();}
 protected function render(){$s=$this->get_settings_for_display();?><div class="tt-brands"><?php foreach($s['items'] as $i):?><a href="<?php echo esc_url($i['url']['url']??'#');?>" class="tt-brand"><?php if(!empty($i['logo']['url'])):?><img src="<?php echo esc_url($i['logo']['url']);?>" alt="<?php echo esc_attr($i['name']);?>"><?php else:?><strong><?php echo esc_html($i['name']);?></strong><?php endif;?></a><?php endforeach;?></div><style>.tt-brands{display:grid;grid-template-columns:repeat(6,1fr);gap:14px}.tt-brand{height:100px;display:flex;align-items:center;justify-content:center;border:1px solid #e0e6ea;border-radius:14px;background:#fff;padding:18px;color:#10212d;text-decoration:none}.tt-brand img{max-width:100%;max-height:55px;object-fit:contain}@media(max-width:900px){.tt-brands{grid-template-columns:repeat(3,1fr)}}@media(max-width:520px){.tt-brands{grid-template-columns:repeat(2,1fr)}}</style><?php }
}\Elementor\Plugin::instance()->widgets_manager->register(new Terttus_Brand_Grid_Widget());